#include "resident/kernel/catalog_section_observation.hpp"
// 雇用工资只从原LE应付/收据派生；预约总额逐笔读取原钱包，不建立托管余额。
#include "estate_employment_internal.hpp"
#include "../estate_title_history.hpp"
#include "estate_employment_codec.hpp"
