namespace hanmo::resident::estate_employment_detail {
Outcome<ActorAgeRead> read_employment_actor_age(const EstateEmploymentContext& x,const StableId& actor,Integer tick,const StableId& fact){
 if(x.common_catalog.family_birth_identity_enabled!=bool(x.births))return {false,{},common_failure("EmploymentBirthAgeSourceRequired",actor).error};
 if(fact.empty()){if(tick!=x.common.tick())return {false,{},common_failure("ActorAgeCurrentBoundaryMismatch",actor).error};return x.births?read_actor_age(x.common,x.common_catalog,*x.births,actor):read_actor_age(x.common,x.common_catalog,actor);}
 return x.births?read_actor_age_before_fact(x.common,x.common_catalog,*x.births,actor,tick,fact):read_actor_age_before_fact(x.common,x.common_catalog,actor,tick,fact);
}
Outcome<Integer> observed_tick(const EstateEmploymentContext& x){Integer limit=x.common.tick();if(x.phase){if(limit==INT64_MAX||x.phase->from_tick!=limit||x.phase->to_tick!=limit+1)return {false,0,common_failure("EstateEmploymentPhaseMismatch").error};limit=x.phase->to_tick;}if(x.state.version!=1||x.catalog.version!=1||x.state.initialized_tick<0||x.state.last_step_tick<x.state.initialized_tick||x.state.last_step_tick>limit||(!x.phase&&x.state.last_step_tick!=limit)||x.economy.last_step_tick<x.state.last_step_tick||x.economy.last_step_tick>limit)return {false,0,common_failure("EstateEmploymentTickMismatch").error};return {true,limit,{}};}
Outcome<Integer> reservation_cap(Integer n,Integer d,Integer ticks){Integer total=0;if(n<=0||d<=0||ticks<=0||!multiply(n,ticks,total))return {false,0,common_failure("EstateEmploymentWageOverflow").error};Integer result=total/d;if(total%d&&!add(result,1,result))return {false,0,common_failure("EstateEmploymentWageOverflow").error};return {true,result,{}};}
const EstateEmploymentContract* obligation_contract(const EstateEmploymentState& s,const StableId& id){for(const auto& row:s.contracts.rows())if(!id.empty()&&row.second.obligation_id==id)return &row.second;return nullptr;}
Outcome<WageTotals> wage_totals(const EstateEmploymentContext& x,const EstateEmploymentContract& contract){WageTotals out;for(const auto& row:x.state.services.rows())if(row.second.contract_id==contract.id){if(!add(out.served,1,out.served))return {false,{},common_failure("EstateEmploymentWageOverflow").error};}for(const auto& row:x.economy.arrears.rows())if(row.second.obligation_id==contract.obligation_id){if(row.second.original_due<0||row.second.paid_amount<0||row.second.paid_amount>row.second.original_due||!add(out.earned,row.second.original_due,out.earned)||!add(out.paid,row.second.paid_amount,out.paid))return {false,{},common_failure("InvalidEmploymentArrear",row.first).error};}if(!contract.obligation_id.empty()){const auto* remainder=x.economy.obligation_remainders.find(contract.obligation_id);if(!remainder)return {false,{},common_failure("MissingEmploymentRemainder",contract.id).error};out.remainder=*remainder;}return {true,out,{}};}
Outcome<Integer> actual_reservation(const CommonStore& c,const EstateEmploymentContract& contract){const auto* wallet=c.wallet(contract.terms.payer_wallet_id);if(!wallet)return {false,0,common_failure("MissingEmploymentWallet",contract.id).error};bool found=false;Integer total=0;for(const auto& value:wallet->reserved)if(value.action_id==ReservationRef{ReservationRef::Kind::contract,contract.id}){if(found||value.amount<0)return {false,0,common_failure("InvalidEmploymentReservation",contract.id).error};found=true;total=value.amount;}return {true,total,{}};}
Status validate_catalog(const EstateEmploymentContext& x){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 21, "EstateEmploymentContext", "validate_catalog", &x);
if(x.catalog.version!=1||!x.economy_catalog.enabled||!x.interaction_catalog)return common_failure("EstateEmploymentDependenciesRequired");if(x.catalog.policies.empty()||x.catalog.policies.size()>4096)return common_failure("EstateEmploymentPolicyLimit");std::map<std::tuple<StableId,StableId,StableId>,Integer> node_counts;for(const auto& row:x.catalog.policies.rows()){const auto& p=row.second;const auto* estate=x.estate_catalog.estates.find(p.estate_id);const auto* rate=x.economy_catalog.rates.find(p.rate_profile);if(row.first!=p.id||!estate||(p.job!="labor"&&p.job!="guard"&&p.job!="manager")||!rate||rate->per_capita||rate->numerator<=0||rate->denominator<=0||p.service_ticks<=0||p.service_ticks>720||p.offer_valid_ticks<=0||p.offer_valid_ticks>720)return common_failure("InvalidEstateEmploymentPolicy",row.first);auto cap=reservation_cap(rate->numerator,rate->denominator,p.service_ticks);if(!cap.ok)return {false,{},cap.error};for(const auto& source:{std::make_pair(p.offer_dialogue_id,p.offer_node_id),std::make_pair(p.worker_dialogue_id,p.worker_node_id)}){const DialogueNode* node=nullptr;for(const auto& d:x.interaction_catalog->dialogues)if(d.id==source.first)for(const auto& n:d.nodes)if(n.id==source.second){if(node)return common_failure("AmbiguousEmploymentNode",p.id);node=&n;}if(!node||(node->kind!="say"&&node->kind!="choice"))return common_failure("EstateEmploymentNodeRequired",p.id);}
 const bool offer=!p.provider_offer_dialogue_id.empty()||!p.provider_offer_node_id.empty();const bool reply=!p.provider_reply_dialogue_id.empty()||!p.provider_reply_node_id.empty()||!p.provider_reply_decision.empty();
 if(reply&&p.provider_reply_decision!="accept"&&p.provider_reply_decision!="decline")return common_failure("EmploymentProviderDecisionRequired",p.id);
 for(const auto& declaration:{std::make_tuple(offer,p.provider_offer_dialogue_id,p.provider_offer_node_id),std::make_tuple(reply,p.provider_reply_dialogue_id,p.provider_reply_node_id)})if(std::get<0>(declaration)){const DialogueNode* node=nullptr;for(const auto& d:x.interaction_catalog->dialogues)if(d.id==std::get<1>(declaration))for(const auto& n:d.nodes)if(n.id==std::get<2>(declaration)){if(node)return common_failure("AmbiguousEmploymentNode",p.id);node=&n;}if(!node||node->kind!="say"||node->speaker.empty()||node->speaker=="$player")return common_failure("EmploymentProviderNodeRequired",p.id);}
 for(const auto& source:{std::make_tuple(StableId{"offer"},p.offer_dialogue_id,p.offer_node_id),std::make_tuple(StableId{"provider_offer"},p.provider_offer_dialogue_id,p.provider_offer_node_id)})if(!std::get<1>(source).empty()&&++node_counts[source]>50)return common_failure("EstateEmploymentNodeLimit",p.id);
 }return common_success();}
Outcome<EstateEmploymentTerms> freeze_terms(const EstateEmploymentContext& x,const EstateEmploymentPolicy& p,const StableId& worker){const auto* estate=x.estates.estates.find(p.estate_id);const auto* authored=x.estate_catalog.estates.find(p.estate_id);const auto* rate=x.economy_catalog.rates.find(p.rate_profile);const auto* actor=x.common.actor(worker);if(!estate||!authored||!rate||!actor)return {false,{},common_failure("InvalidEmploymentSource",p.id).error};if(x.estate_titles){auto title=x.estate_titles->read_current_estate_title(p.estate_id);if(!title.ok)return {false,{},title.error};if(title.value.wallet_id!=authored->wallet_id||title.value.inventory_id!=authored->inventory_id||!owner_equal(title.value.legal_owner,{Owner::Kind::actor,estate->owner_actor_id,{}}))return {false,{},common_failure("EmploymentCurrentTitleMismatch",p.estate_id).error};}auto cap=reservation_cap(rate->numerator,rate->denominator,p.service_ticks);if(!cap.ok)return {false,{},cap.error};Integer expires=0;if(!add(x.common.tick(),p.offer_valid_ticks,expires))return {false,{},common_failure("EstateEmploymentTickOverflow").error};return {true,{p.id,p.estate_id,estate->owner_actor_id,worker,p.job,p.rate_profile,authored->wallet_id,actor->wallet_id,rate->numerator,rate->denominator,p.service_ticks,expires,cap.value},{}};}
bool same_terms(const EstateEmploymentTerms& a,const EstateEmploymentTerms& b){return compare_boundary(dynamic_economy_codec::encode(a),dynamic_economy_codec::encode(b)).exact();}
bool service_performed(const EstateProductionFact& f,const EstateEmploymentTerms& t){if(f.estate_id!=t.estate_id||f.owner_actor_id!=t.employer_actor_id)return false;if(t.job=="labor")return has(f.workers,t.worker_actor_id);if(t.job=="guard")return has(f.guards,t.worker_actor_id);return t.job=="manager"&&f.manager_actor_id==t.worker_actor_id&&has(f.fed,t.worker_actor_id);}
Outcome<StableId> append_fact(CommonStore& c,const StableId& prefix,const StableId& kind,const StableId& domain){auto id=c.next_id(prefix);if(!id.ok)return id;auto added=c.append_fact({id.value,kind,domain});if(!added.ok)return {false,{},added.error};return id;}
}
